ar(--line)}.booking-row strong{display:block;font-size:14px}.small{font-size:12px;color:var(--muted)}.badge{display:inline-block;font-size:12px;padding:4px 10px;border-radius:20px;background:#e5f2e8;color:#176044;width:fit-content}.badge.cancelled{background:#f3eae6;color:#835243}.cancel{border:1px solid #ded6d0;background:white;color:#855b48;border-radius:7px;padding:6px 12px;font-size:12px;width:fit-content}.cancel:hover{background:#fbf2eb}.empty{padding:22px;color:var(--muted)}.assumption{margin-top:24px;border-top:1px solid var(--line);padding-top:16px;font-size:12px;color:var(--muted)}footer{display:flex;justify-content:space-between;font-size:11px;color:var(--muted);margin-top:20px}dialog{border:1px solid var(--line);border-radius:16px;padding:28px;max-width:430px;width:calc(100% - 32px);color:var(--ink);box-shadow:0 20px 80px #12352d30}dialog::backdrop{background:#183b3555}dialog h2{margin-bottom:12px}.summary{background:var(--paper);border-radius:8px;padding:16px;margin:18px 0}.actions{display:flex;justify-content:flex-end;gap:10px}.primary,.secondary{padding:9px 15px;border-radius:8px;border:1px solid var(--green)}.primary{background:var(--green);color:white}.secondary{background:white;color:var(--green)}.toast{position:fixed;bottom:22px;left:50%;transform:translateX(-50%);padding:12px 22px;border-radius:10px;background:#183b35;color:white;box-shadow:0 5px 25px #183b3520;z-index:2;max-width:90%;font-size:14px}.toast:empty{display:none}@media(max-width:700px){.bar{padding:16px 18px;flex-wrap:wrap;gap:12px}.demo{display:none}nav{gap:18px}main{padding:26px 18px}.intro{align-items:stretch;flex-direction:column;gap:16px}h1{font-size:29px}.stats{gap:8px}.stat{padding:10px;display:block}.stat strong{display:block;font-size:24px}.stat span{font-size:11px}.rooms{grid-template-columns:1fr}.scene{height:100px}.section-title{align-items:flex-start}.legend{font-size:11px;gap:8px}.booking-head{display:none}.booking-row{grid-template-columns:1fr 1fr;padding:16px;gap:10px}