<body>
<header><div class="bar"><div class="brand"><span class="logo" aria-hidden="true">▦</span>พร้อมประชุม</div><nav aria-label="เมนูหลัก"><a href="#rooms">ห้องประชุม</a><a href="#bookings">การจองของฉัน</a></nav><span class="demo">MOCK-UP · ออฟไลน์</span></div></header>
<main>
<div class="intro"><div><p class="eyebrow">SPACE TO WORK TOGETHER</p><h1>ห้องพร้อม ไอเดียก็พร้อม</h1><p class="sub">เลือกเวลาที่ใช่ แล้วให้การประชุมเริ่มต้นได้ง่ายขึ้น</p></div><div class="datebox"><label for="date">วันที่ต้องการใช้ห้อง</label><input id="date" type="date" required></div></div>
<div class="stats"><div class="stat"><strong>03</strong><span>ห้องประชุมทั้งหมด</span></div><div class="stat"><strong id="free-count">—</strong><span>ช่วงเวลาว่างในวันที่เลือก</span></div><div class="stat"><strong id="active-count">—</strong><span>การจองที่ยืนยันแล้วทั้งหมด</span></div></div>
<section id="rooms" aria-labelledby="rooms-title"><div class="section-title"><h2 id="rooms-title">เลือกห้องและเวลาว่าง</h2><div class="legend"><span><i class="dot"></i>ว่าง · จองได้</span><span><i class="dot busy"></i>ไม่ว่าง</span></div></div><div id="room-list" class="rooms"></div><p class="hint">กดช่วงเวลาว่าง → ตรวจรายละเอียด → ยืนยันการจอง (2 คลิก) · ทุกช่วงมีระยะเวลา 1 ชั่วโมง</p></section>
<section id="bookings" aria-labelledby="bookings-title"><div class="section-title"><h2 id="bookings-title">การจองของฉัน</h2><span class="small">ทุกวันที่จอง · อัปเดตทันที</span></div><div class="booking-panel"><div class="booking-head" aria-hidden="true"><span>ห้องประชุม / รายการ</span><span>วันและเวลา</span><span>สถานะ</span><span>จัดการ</span></div><div id="booking-list"></div></div></section>
<p class="assumption"><strong>สมมติฐานสำหรับ Mock-up:</strong> ห้องทั้ง 3 ห้อง ชื่อ ความจุ อุปกรณ์ และรายการจองเริ่มต้นเป็นข้อมูลสมมติ ผู้ใช้จำลอง 1 คน จองเป็นช่วงละ 1 ชั่วโมง เวลา 09:00–13:00 น. เริ่มเลือกวันพรุ่งนี้ตามเวลาเครื่อง เก็บข้อมูลเฉพาะเบราว์เซอร์นี้ ไม่มีระบบหลังบ้านหรือการส่งข้อมูลผ่านเครือข่าย</p><footer><span>พร้อมประชุม / MEETING ROOM BOOKING</span><span>ข้อมูลสาธิตเพื่อทดลองใช้งาน</span></footer>
</main>
<dialog id="confirm-dialog" aria-labelledby="dialog-title"><h2 id="dialog-title"></h2><p id="dialog-description" class="sub"></p><div id="dialog-summary" class="summary"></div><div class="actions"><button class="secondary" id="back">กลับ</button><button class="primary" id="confirm">ยืนยันการจอง</button></div></dialog>
<div class="toast" id="notice" role="status" aria-live="polite"></div>
<script>
'"'use strict';
const rooms=[{id:'a',name:'ห้องต้นไม้',capacity:4,equipment:'จอแสดงผล · ไวท์บอร์ด'},{id:'b',name:'ห้องสายน้ำ',capacity:8,equipment:'จอแสดงผล · กล้องประชุม'},{id:'c',name:'ห้องแสงตะวัน',capacity:12,equipment:'โปรเจกเตอร์ · ไวท์บอร์ด'}];
const hours=[9,10,11,12], key='meeting-room-mock-v1';
const localDay=d=>"'`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'"'0')}-"'${String(d.getDate()).padStart(2,'"'0')}"'`;
const tomorrow=new Date();tomorrow.setDate(tomorrow.getDate()+1);
const dateInput=document.querySelector('"'#date');dateInput.min=localDay(new Date());dateInput.value=localDay(tomorrow);
let bookings=[{id:'demo-1',room:'c',date:dateInput.value,hour:10,status:'confirmed',sample:true}],storageWorks=true;
try{const saved=JSON.parse(localStorage.getItem(key));if(Array.isArray(saved)&&saved.every(b=>b&&typeof b.id==='string'&&rooms.some(r=>r.id===b.room)&&/"'^'"\\d{4}-\\d{2}-\\d{2}"'$/.test(b.date)&&hours.includes(b.hour)&&['"'confirmed','cancelled'].includes(b.status)))bookings=saved;}catch(e){storageWorks=false;}
const roomList=document.querySelector('#room-list'),bookingList=document.querySelector('#booking-list'),dialog=document.querySelector('#confirm-dialog');
let pending=null,noticeTimer;
const time=h=>"'`${String(h).padStart(2,'"'0')}:00–"'${String(h+1).padStart(2,'"'0')}:00"'`;
const displayDate=d=>new Date(d+'"'T12:00:00').toLocaleDateString('th-TH',{day:'numeric',month:'short',year:'numeric'});
const occupied=(r,d,h)=>bookings.some(b=>b.room===r&&b.date===d&&b.hour===h&&b.status==='confirmed');
const isPast=(d,h)=>new Date(d+"'`T${String(h).padStart(2,'"'0')}:00:00"'`)<=new Date();
function notify(message){const n=document.querySelector('"'#notice');n.textContent=message;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>n.textContent='',5000);}
function persist(){try{localStorage.setItem(key,JSON.stringify(bookings));}catch(e){storageWorks=false;}}
function render(){
 let free=0;roomList.replaceChildren();
 rooms.forEach((r,i)=>{const article=document.createElement('article');article.className='room';article.setAttribute('aria-label',r.name);article.innerHTML="'`<div class="scene" aria-hidden="true"><span class="room-no">ROOM 0${i+1}</span></div><div class="room-content"><h3>${r.name}</h3><p class="meta">${r.capacity} ที่นั่ง · ${r.equipment}</p><div class="slots"></div></div>`;
 hours.forEach(h=>{const busy=occupied(r.id,dateInput.value,h),past=isPast(dateInput.value,h);const button=document.createElement('"'button');button.className='slot';button.disabled=busy||past;const state=busy?'ไม่ว่าง':past?'ผ่านเวลาแล้ว':'ว่าง · จอง';button.innerHTML="'`<strong>${time(h)}</strong>${state}`;button.setAttribute('"'aria-label',"'`${state} ${r.name} ${time(h)}`);if(!busy&&!past)free++;button.addEventListener('"'click',()=>openConfirm({action:'book',room:r.id,date:dateInput.value,hour:h}));article.querySelector('.slots').append(button);});roomList.append(article);});
 document.querySelector('#free-count').textContent=String(free).padStart(2,'0');document.querySelector('#active-count').textContent=String(bookings.filter(b=>b.status==='confirmed').length).padStart(2,'0');bookingList.replaceChildren();
 if("'!bookings.length){bookingList.innerHTML='"'<p class=\"empty\">ยังไม่มีการจอง เลือกช่วงเวลาว่างด้านบนเพื่อเริ่มต้น</p>';}
 [...bookings].reverse().forEach(b=>{const r=rooms.find(r=>r.id===b.room),row=document.createElement('div');row.className='booking-row';row.dataset.bookingId=b.id;row.setAttribute('role','group');row.setAttribute('aria-label',"'`การจอง ${r.name} ${time(b.hour)}`);row.innerHTML=`<div><strong>${r.name}</strong><span class="small">${b.sample?'"'รายการเริ่มต้น (สมมติ)':'การจองของคุณ (สาธิต)'}</span></div><div><strong>"'${displayDate(b.date)}</strong><span class="small">${time(b.hour)} น.</span></div><span class="badge ${b.status==='"'cancelled'?'cancelled':''}\">"'${b.status==='"'confirmed'?'ยืนยันแล้ว':'ยกเลิกแล้ว'}</span><div class=\"manage\"></div>"'`;
 if(b.status==='"'confirmed'){const button=document.createElement('button');button.className='cancel';button.textContent='ยกเลิกการจอง';button.setAttribute('aria-label',"'`ยกเลิกการจอง ${r.name} ${time(b.hour)}`);button.addEventListener('"'click',()=>openConfirm({action:'cancel',id:b.id,room:b.room,date:b.date,hour:b.hour}));row.querySelector('.manage').append(button);}else{row.querySelector('.manage').innerHTML='<span class=\"small\">คืนช่วงเวลาแล้ว</span>';}bookingList.append(row);});
}
function openConfirm(data){pending=data;const r=rooms.find(r=>r.id===data.room),cancel=data.action==='cancel';document.querySelector('#dialog-title').textContent=cancel?'ยกเลิกการจองนี้?':'ยืนยันห้องที่เลือก';document.querySelector('#dialog-description').textContent=cancel?'หลังยกเลิก ช่วงเวลานี้จะเปิดให้จองอีกครั้ง':'ตรวจสอบห้องและเวลาก่อนยืนยัน';document.querySelector('#dialog-summary').textContent="'`${r.name} · ${displayDate(data.date)} · ${time(data.hour)} น.`;document.querySelector('"'#confirm').textContent=cancel?'ยืนยันการยกเลิก':'ยืนยันการจอง';dialog.showModal();}
document.querySelector('#back').addEventListener('click',()=>{pending=null;dialog.close();});dialog.addEventListener('cancel',()=>pending=null);
document.querySelector('#confirm').addEventListener('click',()=>{if("'!pending)return;const p=pending;pending=null;dialog.close();if(p.action==='"'book'){if(occupied(p.room,p.date,p.hour)||isPast(p.date,p.hour)){notify('ช่วงเวลานี้ไม่ว่าง กรุณาเลือกเวลาอื่น');render();return;}bookings.push({id:'booking-'+Date.now()+'-'+Math.random().toString(36).slice(2),room:p.room,date:p.date,hour:p.hour,status:'confirmed',sample:false});}else{const b=bookings.find(b=>b.id===p.id);if(b)b.status='cancelled';}persist();render();notify((p.action==='book'?'จองสำเร็จ · สถานะยืนยันแล้ว':'ยกเลิกสำเร็จ · คืนช่วงเวลาแล้ว')+(storageWorks?'':' · เก็บข้อมูลได้เฉพาะหน้านี้'));});
dateInput.addEventListener('change',()=>{if("'!dateInput.value||dateInput.value<dateInput.min){dateInput.value=localDay(tomorrow);notify('"'กรุณาเลือกวันนี้หรือวันถัดไป');}render();});
render();
</script>
</body>
</html>
EOF
